errs = {}
for name, predict in methods.items():
    e = []
    for i in range(n):
        keep = np.arange(n) != i
        pred = predict(P[keep], z[keep], P[i])
        e.append(pred - z[i])
    errs[name] = np.array(e)
    rmse = np.sqrt(np.mean(errs[name] ** 2))
    print(name, round(rmse, 2))
